package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.network.RetrofitClient
import fp.practices.ocularis_mobile.data.model.auth.AuthUserInfo
import fp.practices.ocularis_mobile.data.repository.AuthRepository
import fp.practices.ocularis_mobile.util.Logger
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * Estado UI de la autenticación.
 */
data class AuthUiState(
    val isCheckingSession: Boolean = true,
    val isLoading: Boolean = false,
    val error: String? = null,
    val accessToken: String? = null,
    val userInfo: AuthUserInfo? = null,
    val roles: Set<String> = emptySet()
) {
    val isAuthenticated: Boolean
        get() = !accessToken.isNullOrBlank()
}

/**
 * ViewModel que gestiona la autenticación, sesión y estado del usuario.
 */
class AuthViewModel(
    private val repository: AuthRepository = AuthRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

    init {
        observeExternalSessionInvalidation()
        restoreSession()
    }

    private fun observeExternalSessionInvalidation() {
        viewModelScope.launch {
            RetrofitClient.tokenStore.accessTokenFlow.collectLatest { token ->
                if (token.isNullOrBlank()) {
                    _uiState.update {
                        it.copy(
                            isCheckingSession = false,
                            isLoading = false,
                            accessToken = null,
                            userInfo = null,
                            roles = emptySet(),
                            error = null
                        )
                    }
                }
            }
        }
    }

    /**
     * Restaura la sesión desde tokens locales y renueva si es posible.
     */
    fun restoreSession() {
        viewModelScope.launch {
            _uiState.update { it.copy(isCheckingSession = true, error = null) }
            val (token, cachedUser) = repository.restoreSession()

            if (token.isNullOrBlank()) {
                _uiState.update {
                    it.copy(
                        isCheckingSession = false,
                        accessToken = null,
                        userInfo = null,
                        roles = emptySet(),
                        error = null
                    )
                }
                return@launch
            }

            val refreshed = repository.refreshSession()
            val finalUser = if (refreshed) {
                runCatching { repository.fetchMe() }.getOrNull()
            } else {
                cachedUser
            }

            if (refreshed) {
                val (newToken, _) = repository.restoreSession()
                _uiState.update {
                    it.copy(
                        isCheckingSession = false,
                        accessToken = newToken,
                        userInfo = finalUser,
                        roles = normalizeRoles(finalUser?.roles),
                        error = null
                    )
                }
            } else {
                repository.logout()
                _uiState.update {
                    it.copy(
                        isCheckingSession = false,
                        accessToken = null,
                        userInfo = null,
                        roles = emptySet(),
                        error = null
                    )
                }
            }
        }
    }

    /**
     * Inicia sesión con las credenciales proporcionadas.
     * @param username nombre de usuario
     * @param password contraseña
     */
    fun login(username: String, password: String) {
        Logger.d("AuthViewModel", "Intentando login para usuario: $username")
        if (username.isBlank() || password.isBlank()) {
            _uiState.update { it.copy(error = "Usuario y contraseña son obligatorios") }
            return
        }

        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            runCatching {
                val user = repository.login(username.trim(), password)
                val (token, _) = repository.restoreSession()
                _uiState.update {
                    it.copy(
                        isLoading = false,
                        accessToken = token,
                        userInfo = user,
                        roles = normalizeRoles(user.roles),
                        error = null
                    )
                }
            }.onFailure { ex ->
                _uiState.update {
                    it.copy(
                        isLoading = false,
                        error = ex.message ?: "No se pudo iniciar sesión"
                    )
                }
            }
        }
    }

    /**
     * Cierra sesión y limpia el estado de autenticación.
     */
    fun logout() {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            repository.logout()
            _uiState.update {
                it.copy(
                    isLoading = false,
                    accessToken = null,
                    userInfo = null,
                    roles = emptySet(),
                    error = null
                )
            }
        }
    }

    /**
     * Limpia el mensaje de error del estado.
     */
    fun clearError() {
        _uiState.update { it.copy(error = null) }
    }

    /**
     * Normaliza los roles eliminando prefijos y convirtiendo a mayúsculas.
     * @param roles lista de roles crudos
     * @return conjunto de roles normalizados
     */
    private fun normalizeRoles(roles: List<String>?): Set<String> {
        return roles.orEmpty()
            .map { raw -> raw.trim().uppercase().removePrefix("ROLE_") }
            .filter { it.isNotBlank() }
            .toSet()
    }
}

package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.network.RetrofitClient
import fp.practices.ocularis_mobile.data.model.auth.AuthUserInfo
import fp.practices.ocularis_mobile.data.repository.AuthRepository
import fp.practices.ocularis_mobile.util.Logger
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * Estado UI de la autenticación.
 */
data class AuthUiState(
    val isCheckingSession: Boolean = true,
    val isLoading: Boolean = false,
    val error: String? = null,
    val accessToken: String? = null,
    val userInfo: AuthUserInfo? = null,
    val roles: Set<String> = emptySet()
) {
    val isAuthenticated: Boolean
        get() = !accessToken.isNullOrBlank()
}

/**
 * ViewModel que gestiona la autenticación, sesión y estado del usuario.
 */
class AuthViewModel(
    private val repository: AuthRepository = AuthRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

    init {
        observeExternalSessionInvalidation()
        restoreSession()
    }

    private fun observeExternalSessionInvalidation() {
        viewModelScope.launch {
            RetrofitClient.tokenStore.accessTokenFlow.collectLatest { token ->
                if (token.isNullOrBlank()) {
                    _uiState.update {
                        it.copy(
                            isCheckingSession = false,
                            isLoading = false,
                            accessToken = null,
                            userInfo = null,
                            roles = emptySet(),
                            error = null
                        )
                    }
                }
            }
        }
    }

    /**
     * Restaura la sesión desde tokens locales y renueva si es posible.
     */
    fun restoreSession() {
        viewModelScope.launch {
            _uiState.update { it.copy(isCheckingSession = true, error = null) }
            val (token, cachedUser) = repository.restoreSession()

            if (token.isNullOrBlank()) {
                _uiState.update {
                    it.copy(
                        isCheckingSession = false,
                        accessToken = null,
                        userInfo = null,
                        roles = emptySet(),
                        error = null
                    )
                }
                return@launch
            }

            val refreshed = repository.refreshSession()
            val finalUser = if (refreshed) {
                runCatching { repository.fetchMe() }.getOrNull()
            } else {
                cachedUser
            }

            if (refreshed) {
                val (newToken, _) = repository.restoreSession()
                _uiState.update {
                    it.copy(
                        isCheckingSession = false,
                        accessToken = newToken,
                        userInfo = finalUser,
                        roles = normalizeRoles(finalUser?.roles),
                        error = null
                    )
                }
            } else {
                repository.logout()
                _uiState.update {
                    it.copy(
                        isCheckingSession = false,
                        accessToken = null,
                        userInfo = null,
                        roles = emptySet(),
                        error = null
                    )
                }
            }
        }
    }

    /**
     * Inicia sesión con las credenciales proporcionadas.
     * @param username nombre de usuario
     * @param password contraseña
     */
    fun login(username: String, password: String) {
        Logger.d("AuthViewModel", "Intentando login para usuario: $username")
        if (username.isBlank() || password.isBlank()) {
            _uiState.update { it.copy(error = "Usuario y contraseña son obligatorios") }
            return
        }

        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            runCatching {
                val user = repository.login(username.trim(), password)
                val fetched = runCatching { repository.fetchMe() }.getOrNull()
                val finalUser = fetched ?: user
                val (token, _) = repository.restoreSession()
                _uiState.update {
                    it.copy(
                        isLoading = false,
                        accessToken = token,
                        userInfo = finalUser,
                        roles = normalizeRoles(finalUser.roles),
                        error = null
                    )
                }
            }.onFailure { ex ->
                _uiState.update {
                    it.copy(
                        isLoading = false,
                        error = ex.message ?: "No se pudo iniciar sesión"
                    )
                }
            }
        }
    }

    /**
     * Cierra sesión y limpia el estado de autenticación.
     */
    fun logout() {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            repository.logout()
            _uiState.update {
                it.copy(
                    isLoading = false,
                    accessToken = null,
                    userInfo = null,
                    roles = emptySet(),
                    error = null
                )
            }
        }
    }

    /**
     * Limpia el mensaje de error del estado.
     */
    fun clearError() {
        _uiState.update { it.copy(error = null) }
    }

    /**
     * Normaliza los roles eliminando prefijos y convirtiendo a mayúsculas.
     * @param roles lista de roles crudos
     * @return conjunto de roles normalizados
     */
    private fun normalizeRoles(roles: List<String>?): Set<String> {
        return roles.orEmpty()
            .map { raw -> raw.trim().uppercase().removePrefix("ROLE_") }
            .filter { it.isNotBlank() }
            .toSet()
    }
}

package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.model.ContactMessageDTO
import fp.practices.ocularis_mobile.data.repository.ContactRepository
import kotlinx.coroutines.launch

class ContactViewModel(
    private val repository: ContactRepository = ContactRepository()
) : ViewModel() {
    private val _isSending = MutableLiveData(false)
    val isSending: LiveData<Boolean> = _isSending

    private val _error = MutableLiveData<String?>(null)
    val error: LiveData<String?> = _error

    private val _message = MutableLiveData<String?>(null)
    val message: LiveData<String?> = _message

    fun sendMessage(message: ContactMessageDTO) {
        viewModelScope.launch {
            _isSending.value = true
            _error.value = null
            _message.value = null
            try {
                val ok = repository.sendMessage(message)
                if (ok) {
                    _message.value = "Mensaje enviado"
                } else {
                    _error.value = "No se pudo enviar el mensaje"
                }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al enviar el mensaje"
            } finally {
                _isSending.value = false
            }
        }
    }

    fun clearMessage() {
        _message.value = null
    }

    fun clearError() {
        _error.value = null
    }
}

package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.model.ContactMessageDTO
import fp.practices.ocularis_mobile.data.repository.ContactRepository
import kotlinx.coroutines.launch

class ContactViewModel(
    private val repository: ContactRepository = ContactRepository()
) : ViewModel() {
    private val _isSending = MutableLiveData(false)
    val isSending: LiveData<Boolean> = _isSending

    private val _error = MutableLiveData<String?>(null)
    val error: LiveData<String?> = _error

    private val _message = MutableLiveData<String?>(null)
    val message: LiveData<String?> = _message

    fun sendMessage(message: ContactMessageDTO) {
        viewModelScope.launch {
            _isSending.value = true
            _error.value = null
            _message.value = null
            try {
                val response = repository.sendMessage(message)
                if (response.status.equals("success", ignoreCase = true)) {
                    _message.value = response.message ?: "Mensaje enviado"
                } else {
                    _error.value = response.message ?: "No se pudo enviar el mensaje"
                }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al enviar el mensaje"
            } finally {
                _isSending.value = false
            }
        }
    }

    fun clearMessage() {
        _message.value = null
    }

    fun clearError() {
        _error.value = null
    }
}

package fp.practices.ocularis_mobile.ui.screens

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
