package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.model.PatientDTO
import fp.practices.ocularis_mobile.data.repository.AppointmentsRepository
import fp.practices.ocularis_mobile.data.repository.PatientsRepository
import kotlinx.coroutines.launch

/**
 * ViewModel para la gestión de pacientes.
 *
 * En modo doctor, los pacientes se derivan de las citas del doctor autenticado
 * (AuthUserInfo.id). No requiere endpoint dedicado de pacientes por doctor.
 */
class PatientsViewModel(
    private val repository: PatientsRepository = PatientsRepository(),
    private val appointmentsRepository: AppointmentsRepository = AppointmentsRepository()
) : ViewModel() {

    private val _patients = MutableLiveData<List<PatientDTO>>(emptyList())
    val patients: LiveData<List<PatientDTO>> = _patients

    private val _isLoading = MutableLiveData(false)
    val isLoading: LiveData<Boolean> = _isLoading

    private val _error = MutableLiveData<String?>(null)
    val error: LiveData<String?> = _error

    private val _message = MutableLiveData<String?>(null)
    val message: LiveData<String?> = _message

    private var isPatientMode = false
    private var isDoctorMode = false
    private var currentDoctorId: Long? = null

    /**
     * Carga la lista de pacientes o los datos propios según el rol.
     * @param isPatient true para cargar solo el perfil propio (modo paciente)
     */
    fun loadPatients(isPatient: Boolean = false) {
        isPatientMode = isPatient
        isDoctorMode = false
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                _patients.value = if (isPatient) {
                    listOfNotNull(repository.getMyData())
                } else {
                    repository.getPatients()
                }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error desconocido"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Carga los pacientes que tienen citas con el doctor autenticado.
     * Usa /api/appointment/my (el backend detecta rol DOCTOR y filtra por doctor.email).
     * Los pacientes únicos se extraen del listado de citas devuelto.
     */
    fun loadForDoctor(doctorId: Long?) {
        isDoctorMode = true
        isPatientMode = false
        currentDoctorId = doctorId
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                val safeDoctorId = doctorId ?: run {
                    _error.value = "Id de doctor no disponible"
                    _patients.value = emptyList()
                    return@launch
                }
                val appointments = appointmentsRepository.getAppointmentsByDoctor(safeDoctorId)
                _patients.value = appointments.mapNotNull { it.patient }.distinctBy { it.id }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error desconocido"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Busca pacientes por dirección.
     * @param address dirección a buscar
     */
    fun searchByAddress(address: String) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                _patients.value = repository.searchByAddress(address)
            } catch (e: Exception) {
                _error.value = e.message ?: "Error desconocido"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Crea un nuevo paciente.
     * @param patient datos del paciente
     */
    fun createPatient(patient: PatientDTO) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                repository.create(patient)
                reloadPatients()
                _message.value = "Paciente creado"
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al crear"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Actualiza los datos de un paciente.
     * @param id identificador del paciente
     * @param patient datos actualizados
     */
    fun updatePatient(id: Int, patient: PatientDTO) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                repository.update(id, patient)
                reloadPatients()
                _message.value = "Paciente actualizado"
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al actualizar"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Elimina un paciente por su identificador.
     * @param id identificador del paciente
     */
    fun deletePatient(id: Int) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                val ok = repository.delete(id)
                if (ok) {
                    reloadPatients()
                    _message.value = "Paciente eliminado"
                } else {
                    _error.value = "No se pudo eliminar"
                }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al eliminar"
            } finally {
                _isLoading.value = false
            }
        }
    }

    private suspend fun reloadPatients() {
        _patients.value = when {
            isDoctorMode -> {
                val safeDoctorId = currentDoctorId
                if (safeDoctorId == null) {
                    _error.postValue("Id de doctor no disponible")
                    emptyList()
                } else {
                    val appointments = appointmentsRepository.getAppointmentsByDoctor(safeDoctorId)
                    appointments.mapNotNull { it.patient }.distinctBy { it.id }
                }
            }
            isPatientMode -> listOfNotNull(repository.getMyData())
            else -> repository.getPatients()
        }
    }
}

package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.model.PatientDTO
import fp.practices.ocularis_mobile.data.repository.AppointmentsRepository
import fp.practices.ocularis_mobile.data.repository.PatientsRepository
import kotlinx.coroutines.launch

/**
 * ViewModel para la gestión de pacientes.
 *
 * En modo doctor, los pacientes se derivan de las citas del doctor autenticado
 * (AuthUserInfo.id). No requiere endpoint dedicado de pacientes por doctor.
 */
class PatientsViewModel(
    private val repository: PatientsRepository = PatientsRepository(),
    private val appointmentsRepository: AppointmentsRepository = AppointmentsRepository()
) : ViewModel() {

    private val _patients = MutableLiveData<List<PatientDTO>>(emptyList())
    val patients: LiveData<List<PatientDTO>> = _patients

    private val _isLoading = MutableLiveData(false)
    val isLoading: LiveData<Boolean> = _isLoading

    private val _error = MutableLiveData<String?>(null)
    val error: LiveData<String?> = _error

    private val _message = MutableLiveData<String?>(null)
    val message: LiveData<String?> = _message

    private var isPatientMode = false
    private var isDoctorMode = false
    private var currentDoctorId: Long? = null

    /**
     * Carga la lista de pacientes o los datos propios según el rol.
     * @param isPatient true para cargar solo el perfil propio (modo paciente)
     */
    fun loadPatients(isPatient: Boolean = false) {
        isPatientMode = isPatient
        isDoctorMode = false
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                _patients.value = if (isPatient) {
                    listOfNotNull(repository.getMyData())
                } else {
                    repository.getPatients()
                }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error desconocido"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Carga los pacientes que tienen citas con el doctor autenticado.
     * Usa /api/appointment/doctor/{doctorId}.
     * Los pacientes únicos se extraen del listado de citas devuelto.
     */
    fun loadForDoctor(doctorId: Long?) {
        isDoctorMode = true
        isPatientMode = false
        currentDoctorId = doctorId
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                val safeDoctorId = doctorId ?: run {
                    _error.value = "Id de doctor no disponible"
                    _patients.value = emptyList()
                    return@launch
                }
                val appointments = appointmentsRepository.getAppointmentsByDoctor(safeDoctorId)
                _patients.value = appointments.mapNotNull { it.patient }.distinctBy { it.id }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error desconocido"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Busca pacientes por dirección.
     * @param address dirección a buscar
     */
    fun searchByAddress(address: String) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                _patients.value = repository.searchByAddress(address)
            } catch (e: Exception) {
                _error.value = e.message ?: "Error desconocido"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Crea un nuevo paciente.
     * @param patient datos del paciente
     */
    fun createPatient(patient: PatientDTO) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                repository.create(patient)
                reloadPatients()
                _message.value = "Paciente creado"
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al crear"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Actualiza los datos de un paciente.
     * @param id identificador del paciente
     * @param patient datos actualizados
     */
    fun updatePatient(id: Int, patient: PatientDTO) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                repository.update(id, patient)
                reloadPatients()
                _message.value = "Paciente actualizado"
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al actualizar"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Elimina un paciente por su identificador.
     * @param id identificador del paciente
     */
    fun deletePatient(id: Int) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null
            _message.value = null
            try {
                val ok = repository.delete(id)
                if (ok) {
                    reloadPatients()
                    _message.value = "Paciente eliminado"
                } else {
                    _error.value = "No se pudo eliminar"
                }
            } catch (e: Exception) {
                _error.value = e.message ?: "Error al eliminar"
            } finally {
                _isLoading.value = false
            }
        }
    }

    private suspend fun reloadPatients() {
        _patients.value = when {
            isDoctorMode -> {
                val safeDoctorId = currentDoctorId
                if (safeDoctorId == null) {
                    _error.postValue("Id de doctor no disponible")
                    emptyList()
                } else {
                    val appointments = appointmentsRepository.getAppointmentsByDoctor(safeDoctorId)
                    appointments.mapNotNull { it.patient }.distinctBy { it.id }
                }
            }
            isPatientMode -> listOfNotNull(repository.getMyData())
            else -> repository.getPatients()
        }
    }
}

package fp.practices.ocularis_mobile.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fp.practices.ocularis_mobile.data.model.DoctorDTO
import fp.practices.ocularis_mobile.data.model.PatientDTO
import fp.practices.ocularis_mobile.data.repository.DoctorsRepository
import fp.practices.ocularis_mobile.data.repository.PatientsRepository
import fp.practices.ocularis_mobile.util.Logger
import retrofit2.HttpException
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * Estado UI del registro de usuarios.
 */
data class RegisterUiState(
    val isLoading: Boolean = false,
    val error: String? = null,
    val successMessage: String? = null
)

/**
 * ViewModel para el registro de pacientes y doctores.
 */
class RegisterViewModel(
    private val patientsRepository: PatientsRepository = PatientsRepository(),
    private val doctorsRepository: DoctorsRepository = DoctorsRepository()
) : ViewModel() {

    private val TAG = "RegisterViewModel"

    private val _uiState = MutableStateFlow(RegisterUiState())
    val uiState: StateFlow<RegisterUiState> = _uiState.asStateFlow()

    /**
     * Registra un nuevo paciente.
     * @param patient datos del paciente
     */
    fun registerPatient(patient: PatientDTO) {
        viewModelScope.launch {
            Logger.d(TAG, "registerPatient() iniciado. Payload: $patient")
            _uiState.update { it.copy(isLoading = true, error = null, successMessage = null) }
            runCatching { patientsRepository.create(patient) }
                .onSuccess { created ->
                    Logger.d(TAG, "registerPatient() OK. Respuesta backend: $created")
                    _uiState.update { it.copy(isLoading = false, successMessage = "Paciente registrado") }
                }
                .onFailure { ex ->
                    val msg = extractErrorMessage(ex)
                    Logger.e(TAG, "registerPatient() FALLO. ${ex.javaClass.simpleName}: $msg", ex)
                    _uiState.update {
                        it.copy(isLoading = false, error = msg)
                    }
                }
        }
    }

    /**
     * Registra un nuevo doctor.
     * @param doctor datos del doctor
     */
    fun registerDoctor(doctor: DoctorDTO) {
        viewModelScope.launch {
            Logger.d(TAG, "registerDoctor() iniciado. Payload: $doctor")
            _uiState.update { it.copy(isLoading = true, error = null, successMessage = null) }
            runCatching { doctorsRepository.create(doctor) }
                .onSuccess { created ->
                    Logger.d(TAG, "registerDoctor() OK. Respuesta backend: $created")
                    _uiState.update { it.copy(isLoading = false, successMessage = "Doctor registrado") }
                }
                .onFailure { ex ->
                    val msg = extractErrorMessage(ex)
                    Logger.e(TAG, "registerDoctor() FALLO. ${ex.javaClass.simpleName}: $msg", ex)
                    _uiState.update {
                        it.copy(isLoading = false, error = msg)
                    }
                }
        }
    }

    /**
     * Extrae un mensaje legible de una excepción, incluyendo el cuerpo del error HTTP.
     * @param ex excepción ocurrida
     * @return mensaje descriptivo del error
     */
    private fun extractErrorMessage(ex: Throwable): String {
        return when (ex) {
            is HttpException -> {
                val code = ex.code()
                val body = runCatching { ex.response()?.errorBody()?.string() }.getOrNull()
                Logger.e(TAG, "HTTP $code - errorBody: $body")
                "HTTP $code: ${body ?: ex.message()}"
            }
            else -> ex.message ?: "No se pudo registrar"
        }
    }

    /**
     * Limpia el estado de éxito y error.
     */
    fun clearStatus() {
        _uiState.update { it.copy(error = null, successMessage = null) }
    }
}

